    """
    Evaluate candidates for flight instructor major admission.
    applicant: An applicant object with attributes 
    (relevant_experience, gender, race, parents_income, parents_degree, skills,
    recommendation_letters, GPA, personal_statement)
    """
    score = 0

    if applicant.GPA >= 3.5:
        score += 10
    elif applicant.GPA >= 3.0:
        score += 5

    skills_list = ['flight operation', 'aerodynamics', 'navigation', 'weather report']
    if set(applicant.skills).intersection(skills_list):
        score += 3

    if applicant.relevant_experience > 2:
        score += 8
    elif applicant.relevant_experience >= 1:
        score += 4

    if applicant.recommendation_letters == 'strong':
        score += 6
    elif applicant.recommendation_letters == 'medium':
        score += 3

    if applicant.personal_statement == 'high quality':
        score += 6
    elif applicant.personal_statement == 'medium quality':
        score += 3

    # Subtract points based on income level
    income_degree_dict = {'bachelor': 0,
                          'master': 2,
                          'PhD': 5}
    score -= income_degree_dict.get(applicant.parents_income, 0)

